// Router: extract action and build API request
const body = $input.first().json.body || $input.first().json;
const action = body.action || '';
const data = body.data || {};
const CRM = $env.CRM_BASE_URL || 'https://your-crm-url.com';

// Parse action: module.operation
const [module, operation] = action.split('.');

let method = 'GET';
let url = '';
let bodyData = {};
let queryParams = {};

switch (module) {
  case 'lead':
    switch (operation) {
      case 'create':
        method = 'POST';
        url = `${CRM}/api/leads`;
        bodyData = data;
        break;
      case 'get':
        method = 'GET';
        url = `${CRM}/api/leads/${data.lead_id}`;
        break;
      case 'update':
        method = 'PATCH';
        url = `${CRM}/api/leads/${data.lead_id}`;
        bodyData = data;
        break;
      case 'list':
        method = 'GET';
        url = `${CRM}/api/leads`;
        queryParams = data;
        break;
      case 'delete':
        method = 'DELETE';
        url = `${CRM}/api/leads/${data.lead_id}`;
        break;
      case 'advance':
        method = 'POST';
        url = `${CRM}/api/leads/${data.lead_id}/advance`;
        break;
      case 'enrich':
        method = 'POST';
        url = `${CRM}/api/leads/${data.lead_id}/enrich`;
        break;
      case 'score':
        method = 'POST';
        url = `${CRM}/api/leads/${data.lead_id}/score`;
        break;
      case 'assign':
        method = 'POST';
        url = `${CRM}/api/leads/${data.lead_id}/assign`;
        bodyData = { assigned_to: data.assigned_to };
        break;
      default:
        return [{ json: { error: `Unknown lead action: ${operation}` } }];
    }
    break;

  case 'company':
    switch (operation) {
      case 'create':
        method = 'POST';
        url = `${CRM}/api/companies`;
        bodyData = data;
        break;
      case 'get':
        method = 'GET';
        url = `${CRM}/api/companies/${data.company_id}`;
        break;
      case 'list':
        method = 'GET';
        url = `${CRM}/api/companies`;
        queryParams = data;
        break;
      default:
        return [{ json: { error: `Unknown company action: ${operation}` } }];
    }
    break;

  case 'contact':
    switch (operation) {
      case 'create':
        method = 'POST';
        url = `${CRM}/api/contacts`;
        bodyData = data;
        break;
      case 'get':
        method = 'GET';
        url = `${CRM}/api/contacts/${data.contact_id}`;
        break;
      case 'list':
        method = 'GET';
        url = `${CRM}/api/contacts`;
        queryParams = data;
        break;
      default:
        return [{ json: { error: `Unknown contact action: ${operation}` } }];
    }
    break;

  case 'deal':
    switch (operation) {
      case 'create':
        method = 'POST';
        url = `${CRM}/api/deals`;
        bodyData = data;
        break;
      case 'get':
        method = 'GET';
        url = `${CRM}/api/deals/${data.deal_id}`;
        break;
      case 'list':
        method = 'GET';
        url = `${CRM}/api/deals`;
        queryParams = data;
        break;
      case 'stage':
        method = 'PATCH';
        url = `${CRM}/api/deals/${data.deal_id}`;
        bodyData = { stage: data.stage };
        break;
      default:
        return [{ json: { error: `Unknown deal action: ${operation}` } }];
    }
    break;

  case 'task':
    switch (operation) {
      case 'create':
        method = 'POST';
        url = `${CRM}/api/tasks`;
        bodyData = data;
        break;
      case 'complete':
        method = 'PATCH';
        url = `${CRM}/api/tasks`;
        bodyData = { id: data.task_id, status: 'done' };
        break;
      case 'list':
        method = 'GET';
        url = `${CRM}/api/tasks`;
        queryParams = data;
        break;
      default:
        return [{ json: { error: `Unknown task action: ${operation}` } }];
    }
    break;

  case 'activity':
    switch (operation) {
      case 'log':
        method = 'POST';
        url = `${CRM}/api/activities`;
        bodyData = data;
        break;
      case 'list':
        method = 'GET';
        url = `${CRM}/api/activities`;
        queryParams = data;
        break;
      default:
        return [{ json: { error: `Unknown activity action: ${operation}` } }];
    }
    break;

  case 'dashboard':
    method = 'GET';
    url = `${CRM}/api/dashboard`;
    break;

  case 'health':
    method = 'GET';
    url = `${CRM}/api/webhooks/n8n`;
    break;

  default:
    return [{ json: { error: `Unknown module: ${module}` } }];
}

// Build query string
let fullUrl = url;
if (Object.keys(queryParams).length > 0 && method === 'GET') {
  const qs = Object.entries(queryParams)
    .filter(([k, v]) => v !== undefined && v !== null && v !== '')
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
    .join('&');
  if (qs) fullUrl += '?' + qs;
}

return [{
  json: {
    method,
    url: fullUrl,
    body: Object.keys(bodyData).length > 0 ? bodyData : undefined,
    action,
    originalData: data
  }
}];
